(78910, 2807, 327, '<td valign="top">Very nice shot, well done-great color. Kee</td>', 'Very nice shot, well done-great color. Kee', '2002-07-01 19:41:00.000000', NULL, 1),
(78911, 2807, 1005, '<td valign="top">Interesting pattern.  What are these things, really?  Fun shot, well executed.  Photo 9 Transparency 8 total 8</td>', 'Interesting pattern.  What are these things, really?  Fun shot, well executed.  Photo 9 Transparency 8 total 8', '2002-07-01 19:45:00.000000', NULL, 1),
