(78931, 2808, 2382, '<td valign="top">Beautiful colors.  nice composition.  don''t quite understand the title though.</td>', 'Beautiful colors.  nice composition.  don''t quite understand the title though.', '2002-07-02 15:39:00.000000', NULL, 1),
(78932, 2808, 1897, '<td valign="top">I really like the composition, and focus of this shot.  The only thing that I might change is the saturation and or contrast.  It does not really pop out at me.  This is one of my top 5 for the week.  Good effort. 9</td>', 'I really like the composition, and focus of this shot.  The only thing that I might change is the saturation and or contrast.  It does not really pop out at me.  This is one of my top 5 for the week.  Good effort. 9', '2002-07-03 19:06:00.000000', NULL, 1),
(78933, 2808, 2079, '<td valign="top">This is a good entry for this challenge. It has all the elements and is technically sound as well. I like the color contrast, but the picture is not something I might hang on my wall (maybe in the bar). I gave this -6, good luck</td>', 'This is a good entry for this challenge. It has all the elements and is technically sound as well. I like the color contrast, but the picture is not something I might hang on my wall (maybe in the bar). I gave this -6, good luck', '2002-07-03 20:37:00.000000', NULL, 1),
