INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(78947, 2809, 1041, '<td valign="top">that crystal is great.  you may be getting comments that it needs to be cleaned, but i think the texture adds a lot.  what i find rather distracting in this photo is that wavy diagonal thing going across the photo.  i just can''t quite figure out what it is.  i''m sure it''s important (it''s too obvious to be missed while taking the photo), i just don''t get it, and therefore to me it''s distracting.  -- gr8photos (5)</td>', 'that crystal is great.  you may be getting comments that it needs to be cleaned, but i think the texture adds a lot.  what i find rather distracting in this photo is that wavy diagonal thing going across the photo.  i just can''t quite figure out what it is.  i''m sure it''s important (it''s too obvious to be missed while taking the photo), i just don''t get it, and therefore to me it''s distracting.  -- gr8photos (5)', '2002-07-02 12:59:00.000000', NULL, 1),
(78948, 2809, 1005, '<td valign="top">Where''s the lemonaide?  Very, very nice photo.  Sorry to pick, but what are the things all over the prism?  (nicks and chips?)  I don''t know what the squiggly lines are from, but it does add some cool interest.  (what are they??)  Photo 9 Transparency 8 total 9 swash</td>', 'Where''s the lemonaide?  Very, very nice photo.  Sorry to pick, but what are the things all over the prism?  (nicks and chips?)  I don''t know what the squiggly lines are from, but it does add some cool interest.  (what are they??)  Photo 9 Transparency 8 total 9 swash', '2002-07-02 17:09:00.000000', NULL, 1),
(78949, 2809, 772, '<td valign="top">I really like this shot but I''m not really sure that the curvy twig is adding anyting to it.  = 7 - jmsetzler</td>', 'I really like this shot but I''m not really sure that the curvy twig is adding anyting to it.  = 7 - jmsetzler', '2002-07-02 17:10:00.000000', NULL, 1),
(78950, 2809, 1944, '<td valign="top">You''re probably getting hammered by the same people who don''t see anything transparent in mine either, but I like this a lot!</td>', 'You''re probably getting hammered by the same people who don''t see anything transparent in mine either, but I like this a lot!', '2002-07-03 01:39:00.000000', NULL, 1),
(78951, 2809, 1658, '<td valign="top">simply put, a very nice photo.  it has an interesting composition and is striking.  one of my 10''s this week.  good job!</td>', 'simply put, a very nice photo.  it has an interesting composition and is striking.  one of my 10''s this week.  good job!', '2002-07-03 13:04:00.000000', NULL, 1),
(78952, 2809, 554, '<td valign="top">pretty----10</td>', 'pretty----10', '2002-07-03 23:51:00.000000', NULL, 1),
(78953, 2809, 2221, '<td valign="top">very nice shot! the colors are beautiful. good transparency.<br/>why did you add the dark rod (what is it?). i guess you did it on purpose but i think it''s very distracting. it would have looked better without it.</td>', 'very nice shot! the colors are beautiful. good transparency.why did you add the dark rod (what is it?). i guess you did it on purpose but i think it''s very distracting. it would have looked better without it.', '2002-07-06 22:34:00.000000', NULL, 1),
(78954, 2809, 1054, '<td valign="top">Great title, great shot.  It looks like the crestal is dirty though, unless those are imperfections in the crystal itself.</td>', 'Great title, great shot.  It looks like the crestal is dirty though, unless those are imperfections in the crystal itself.', '2002-07-07 11:16:00.000000', NULL, 1),
(78955, 2809, 2422, '<td valign="top">Thanks for all your votes and comments. This is my first entry in a photographic competition, I have only just started in digital photography. I now realise I should have said that the crystal is a snowflake quartz, and the twisty twig didn''t really work.</td>', 'Thanks for all your votes and comments. This is my first entry in a photographic competition, I have only just started in digital photography. I now realise I should have said that the crystal is a snowflake quartz, and the twisty twig didn''t really work.', '2002-07-08 05:08:00.000000', NULL, 0),
(78956, 2810, 2468, '<td valign="top">Wonderful shot, I like it! Colors, contrast and DOF makes a winner, only thing I would like to see is a totally black background, the white speckles takes away from your photo.<br/></td>', 'Wonderful shot, I like it! Colors, contrast and DOF makes a winner, only thing I would like to see is a totally black background, the white speckles takes away from your photo.', '2002-07-01 01:40:00.000000', NULL, 1),
(78957, 2810, 1779, '<td valign="top">nice... : )</td>', 'nice... : )', '2002-07-01 12:41:00.000000', NULL, 1),
(78958, 2810, 741, '<td valign="top">Technically excellent but doesn''t really grab me - leaves me asking what the point of the picture is.</td>', 'Technically excellent but doesn''t really grab me - leaves me asking what the point of the picture is.', '2002-07-01 18:25:00.000000', NULL, 1),
(78959, 2810, 1880, '<td valign="top">Nice picture ....</td>', 'Nice picture ....', '2002-07-01 19:47:00.000000', NULL, 1),
