(79072, 2816, 2199, '<td valign="top">Great photo -- extra point from me for taking a photo of something that would gross out the average voter!</td>', 'Great photo -- extra point from me for taking a photo of something that would gross out the average voter!', '2002-07-05 21:17:00.000000', NULL, 1),
