(79340, 2835, 705, '<td valign="top">Cheeky.  Creative solution to the challenge.  The image itself is kind of boring, outside the context of the challenge.</td>', 'Cheeky.  Creative solution to the challenge.  The image itself is kind of boring, outside the context of the challenge.', '2002-07-03 18:48:00.000000', NULL, 1),
(79341, 2835, 772, '<td valign="top">i really didn''t expect to see xray shots this week.. this is nice :) = 7 - jmsetzler</td>', 'i really didn''t expect to see xray shots this week.. this is nice :) = 7 - jmsetzler', '2002-07-04 00:03:00.000000', NULL, 1),
(79342, 2835, 1944, '<td valign="top">This is an interesting picture, but to me it has no focal point, nowhere for the eye to rest and to focus on a main object of interest.</td>', 'This is an interesting picture, but to me it has no focal point, nowhere for the eye to rest and to focus on a main object of interest.', '2002-07-04 00:09:00.000000', NULL, 1),
