(79344, 2836, 1, '<td valign="top">Nice idea, but I''m not feeling the chosen angle.  Try a different angle for better composure.</td>', 'Nice idea, but I''m not feeling the chosen angle.  Try a different angle for better composure.', '2002-07-01 09:29:00.000000', NULL, 1),
(79345, 2836, 1877, '<td valign="top">I see the "thy word is a lamp..." line so i''m assuming thats why you put these together. I think for this challenge, you should have focused on what you see looking through the glass, not the reflection. The book is kind of distracting too.</td>', 'I see the "thy word is a lamp..." line so i''m assuming thats why you put these together. I think for this challenge, you should have focused on what you see looking through the glass, not the reflection. The book is kind of distracting too.', '2002-07-01 14:42:00.000000', NULL, 1),
(79346, 2836, 327, '<td valign="top">Very nice shot, well done. Kee</td>', 'Very nice shot, well done. Kee', '2002-07-01 17:37:00.000000', NULL, 1),
