INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(79348, 2836, 2263, '<td valign="top">Gotta love the lighting.  Good job with the corresponding scripture (vs. 105)</td>', 'Gotta love the lighting.  Good job with the corresponding scripture (vs. 105)', '2002-07-02 18:36:00.000000', NULL, 1),
(79349, 2836, 1005, '<td valign="top">Very nice, only suggestion is a nit:  Under NUN is an X shadow from the lamp, I would have liked to have seen the whole thing, (was it possible?). Call me square. How to say this without offending you?  Religion is a personal thing, very personal in my circle.  Photo 7 Transparency 6 total 6 swash</td>', 'Very nice, only suggestion is a nit:  Under NUN is an X shadow from the lamp, I would have liked to have seen the whole thing, (was it possible?). Call me square. How to say this without offending you?  Religion is a personal thing, very personal in my circle.  Photo 7 Transparency 6 total 6 swash', '2002-07-03 13:49:00.000000', NULL, 1),
(79350, 2836, 772, '<td valign="top">I like this photo and I REALLY like the way you have done this.. i hope this was intentional with the candle and the "Thy word is a lamp unto my feed, and a light unto my path." = 9 - jmsetzler</td>', 'I like this photo and I REALLY like the way you have done this.. i hope this was intentional with the candle and the "Thy word is a lamp unto my feed, and a light unto my path." = 9 - jmsetzler', '2002-07-03 16:56:00.000000', NULL, 1),
(79351, 2836, 806, '<td valign="top">This is a clever idea.... and the "X" shadow on the page caused by the candle is on "I beseech thee... teach me thy judgements". Don''t know if this was in any way planned, but seems appropriate in a wierd sort of way to the voting at hand! Or maybe I''m just in a weird mood. Anyway. I like it.</td>', 'This is a clever idea.... and the "X" shadow on the page caused by the candle is on "I beseech thee... teach me thy judgements". Don''t know if this was in any way planned, but seems appropriate in a wierd sort of way to the voting at hand! Or maybe I''m just in a weird mood. Anyway. I like it.', '2002-07-03 17:06:00.000000', NULL, 1),
(79352, 2836, 1031, '<td valign="top">Good combination of "related" elements</td>', 'Good combination of "related" elements', '2002-07-06 01:40:00.000000', NULL, 1),
