(79410, 2843, 1005, '<td valign="top">Wicked!  Please explain this one after the fact.  I''m not really knowing what is going on here, but it looks cool.  (Are those goldfish in the water?) WILD!<br/>Photo 8 Transparency 9 total 9 swash</td>', 'Wicked!  Please explain this one after the fact.  I''m not really knowing what is going on here, but it looks cool.  (Are those goldfish in the water?) WILD!Photo 8 Transparency 9 total 9 swash', '2002-07-03 14:13:00.000000', NULL, 1),
(79411, 2843, 509, '<td valign="top">Great picture!  It looks like a cross between water and molten lava.  There seems to be some empty space at the top, but this is very well done, - 9</td>', 'Great picture!  It looks like a cross between water and molten lava.  There seems to be some empty space at the top, but this is very well done, - 9', '2002-07-05 17:46:00.000000', NULL, 1),
(79412, 2843, 811, '<td valign="top">this is a really interesting idea, and I am wanting to know how you did it.  I think it would be more effective if it weren''t cropped off at the bottom, maybe.  I had originally scored this rather low, but after looking at it, i think it deserves higher.  karmat</td>', 'this is a really interesting idea, and I am wanting to know how you did it.  I think it would be more effective if it weren''t cropped off at the bottom, maybe.  I had originally scored this rather low, but after looking at it, i think it deserves higher.  karmat', '2002-07-05 18:25:00.000000', NULL, 1),
(79413, 2843, 573, '<td valign="top">Wow, another "How did you do it?" One of my top ten this week.</td>', 'Wow, another "How did you do it?" One of my top ten this week.', '2002-07-05 18:29:00.000000', NULL, 1),
(79414, 2843, 1031, '<td valign="top">Nice coloring effect</td>', 'Nice coloring effect', '2002-07-06 16:53:00.000000', NULL, 1),
(79415, 2843, 1054, '<td valign="top">Bizarre!  What is that?</td>', 'Bizarre!  What is that?', '2002-07-07 10:13:00.000000', NULL, 1),
(79416, 2843, 2093, '<td valign="top">I shit this at 1/50 of a sec at a fountain jet backlit by the orange light under the water. After taking millions of photos, I finally got one I liked.</td>', 'I shit this at 1/50 of a sec at a fountain jet backlit by the orange light under the water. After taking millions of photos, I finally got one I liked.', '2002-07-09 08:33:00.000000', NULL, 0),
(79417, 2847, 92, '<td valign="top">Nice idea. I think it would score better with a different background and with the coin facing straight up and down.</td>', 'Nice idea. I think it would score better with a different background and with the coin facing straight up and down.', '2002-07-01 03:04:00.000000', NULL, 1),
(79418, 2847, 1202, '<td valign="top">Neat idea, but I feel it would have been better executed if the background would have been less busy.   This would have shown the structure of the bubble more and not have been so distracting.</td>', 'Neat idea, but I feel it would have been better executed if the background would have been less busy.   This would have shown the structure of the bubble more and not have been so distracting.', '2002-07-01 10:10:00.000000', NULL, 1),
(79419, 2847, 641, '<td valign="top">Love how you caught that little star of light and rainbow there.</td>', 'Love how you caught that little star of light and rainbow there.', '2002-07-01 11:20:00.000000', NULL, 1),
