(79516, 2851, 142, '<td valign="top">Nice photo of the White House.  I don''t understand the connection though.</td>', 'Nice photo of the White House.  I don''t understand the connection though.', '2002-07-07 23:05:00.000000', NULL, 1),
(79517, 2851, 2058, '<td valign="top">I gave this a 7 just because I thought it was a really nice shot of the Capitol, and just gave you the benefit of the doubt that I was missing something when it came to the transparency part.  I''m surprised at the number of people here that actually thought it WAS the White House... was this a mistake in naming on your part, or was it part of your commentary?</td>', 'I gave this a 7 just because I thought it was a really nice shot of the Capitol, and just gave you the benefit of the doubt that I was missing something when it came to the transparency part.  I''m surprised at the number of people here that actually thought it WAS the White House... was this a mistake in naming on your part, or was it part of your commentary?', '2002-07-08 12:19:00.000000', NULL, 0),
(79518, 2852, 1959, '<td valign="top">REDRUM, MURDER..very witty!  Great play on words and the relation with the red fluid.</td>', 'REDRUM, MURDER..very witty!  Great play on words and the relation with the red fluid.', '2002-07-01 04:44:00.000000', NULL, 1),
