(79527, 2852, 1041, '<td valign="top">doubly fulfilled the challenge - color and distortion.  :)  however, as for the implementation, your horizon isn''t quite level and the text above the glass (which i would expect to be in focus) looks somewhat oversharpened.  -- gr8photos (3)</td>', 'doubly fulfilled the challenge - color and distortion.  :)  however, as for the implementation, your horizon isn''t quite level and the text above the glass (which i would expect to be in focus) looks somewhat oversharpened.  -- gr8photos (3)', '2002-07-02 10:36:00.000000', NULL, 1),
(79528, 2852, 1856, '<td valign="top">Looks more like red paint that blood.  This might look better if the glass of water were magnifying blood running down the page of the book (as opposed to being dripped in the water).</td>', 'Looks more like red paint that blood.  This might look better if the glass of water were magnifying blood running down the page of the book (as opposed to being dripped in the water).', '2002-07-02 11:57:00.000000', NULL, 1),
