(79723, 2867, 133, '<td valign="top">weird, but I like it</td>', 'weird, but I like it', '2002-07-01 19:35:00.000000', NULL, 1),
(79724, 2867, 509, '<td valign="top">This type of shot I didn''t find too interesting in this challenge.  The blurriness distracts from the transparency, and it looks like a high ISO was used.  There is visible grain in the shadows and on the wall.  On the other hand, the exposure is pretty good, though maybe a closer zoom emphasizing the window would have been better at lighting the scene (and moving the cling wrap and glasses accordingly so that their edges are still in the frame).</td>', 'This type of shot I didn''t find too interesting in this challenge.  The blurriness distracts from the transparency, and it looks like a high ISO was used.  There is visible grain in the shadows and on the wall.  On the other hand, the exposure is pretty good, though maybe a closer zoom emphasizing the window would have been better at lighting the scene (and moving the cling wrap and glasses accordingly so that their edges are still in the frame).', '2002-07-02 01:32:00.000000', NULL, 1),
(79725, 2867, 2146, '<td valign="top">good</td>', 'good', '2002-07-02 02:41:00.000000', NULL, 1),
(79726, 2867, 772, '<td valign="top">This photo is a little ''too'' abstract for me.  The title tells me what I''m looking at though... I really like a photo that is self interpreting, for the most part.  = 6 - jmsetzler</td>', 'This photo is a little ''too'' abstract for me.  The title tells me what I''m looking at though... I really like a photo that is self interpreting, for the most part.  = 6 - jmsetzler', '2002-07-02 13:30:00.000000', NULL, 1),
