(79728, 2867, 1005, '<td valign="top">wierd  -  surreal effect on the dark, ominous side.  Has a hap-hazard look to it.  Photo 7 Transparency 7 total 7 swash</td>', 'wierd  -  surreal effect on the dark, ominous side.  Has a hap-hazard look to it.  Photo 7 Transparency 7 total 7 swash', '2002-07-03 15:15:00.000000', NULL, 1),
