(79745, 2869, 2172, '<td valign="top">This is a really nice shot.  Only thing - I might have cropped just to the glass creating a great abstract.  Good work!<br/>Ruthann</td>', 'This is a really nice shot.  Only thing - I might have cropped just to the glass creating a great abstract.  Good work!Ruthann', '2002-07-05 13:38:00.000000', NULL, 1),
