INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(79748, 2870, 92, '<td valign="top">A PERFECT photo ! I love this one and it fits the challenge so well !!!!! = 10</td>', 'A PERFECT photo ! I love this one and it fits the challenge so well !!!!! = 10', '2002-07-01 04:54:00.000000', NULL, 1),
(79749, 2870, 436, '<td valign="top">great highlight on the cornea.  I wonder if there was a way to diminish the brightness under the lower lash and keep that edge lighting.  Nice macro.</td>', 'great highlight on the cornea.  I wonder if there was a way to diminish the brightness under the lower lash and keep that edge lighting.  Nice macro.', '2002-07-01 09:15:00.000000', NULL, 1),
(79750, 2870, 2011, '<td valign="top">Cool shot.  I like it. Original!</td>', 'Cool shot.  I like it. Original!', '2002-07-01 10:44:00.000000', NULL, 1),
(79751, 2870, 2023, '<td valign="top">Beautiful shot. Great light, nicely done</td>', 'Beautiful shot. Great light, nicely done', '2002-07-01 11:34:00.000000', NULL, 1),
(79752, 2870, 1175, '<td valign="top">WOW!</td>', 'WOW!', '2002-07-01 12:37:00.000000', NULL, 1),
(79753, 2870, 1779, '<td valign="top">nice... : )</td>', 'nice... : )', '2002-07-01 13:50:00.000000', NULL, 1),
(79754, 2870, 2481, '<td valign="top">very nice transparency.  good closeup.</td>', 'very nice transparency.  good closeup.', '2002-07-01 14:55:00.000000', NULL, 1),
(79755, 2870, 1897, '<td valign="top">incredible.  great idea.  This si not something I would hang on the wall, but very unique  great depth- 9</td>', 'incredible.  great idea.  This si not something I would hang on the wall, but very unique  great depth- 9', '2002-07-01 14:58:00.000000', NULL, 1),
(79756, 2870, 2494, '<td valign="top">the detail and ballance are fantastic.  hower, it reminded me of commercial clip art photography.</td>', 'the detail and ballance are fantastic.  hower, it reminded me of commercial clip art photography.', '2002-07-01 16:09:00.000000', NULL, 1),
(79757, 2870, 885, '<td valign="top">Really cool, dude.  I love the highlight on the outside of the eye, and the detail in the eyelashes, and it''s awesome how you can see the background through the sphere.  Does she wear contacts?  If not, I wonder what it would have looked like with them.  Of course I would have liked it better with a [censored]...;-)</td>', 'Really cool, dude.  I love the highlight on the outside of the eye, and the detail in the eyelashes, and it''s awesome how you can see the background through the sphere.  Does she wear contacts?  If not, I wonder what it would have looked like with them.  Of course I would have liked it better with a [censored]...;-)', '2002-07-01 16:24:00.000000', NULL, 1),
(79758, 2870, 133, '<td valign="top">wow, great close up</td>', 'wow, great close up', '2002-07-01 19:32:00.000000', NULL, 1),
(79759, 2870, 327, '<td valign="top">Very nice shot, tad bit over exposed at the bottom --still well done. Good work. Kee</td>', 'Very nice shot, tad bit over exposed at the bottom --still well done. Good work. Kee', '2002-07-01 19:53:00.000000', NULL, 1),
(79760, 2870, 593, '<td valign="top">Fantastic. That is an amazing view that I have never seen done.</td>', 'Fantastic. That is an amazing view that I have never seen done.', '2002-07-01 20:57:00.000000', NULL, 1),
(79761, 2870, 142, '<td valign="top">Wow!  I want to know how you did this.</td>', 'Wow!  I want to know how you did this.', '2002-07-01 21:33:00.000000', NULL, 1),
(79762, 2870, 2079, '<td valign="top">I love this shot, great compesition- this is one of my favorite for this challenge. I hope the hair splitters give this the consideration it deserves. Good Luck - 8<br/>semi-transparent -10<br/>distortion - 2<br/>colors in objects - 7<br/>Be creative - 10<br/></td>', 'I love this shot, great compesition- this is one of my favorite for this challenge. I hope the hair splitters give this the consideration it deserves. Good Luck - 8semi-transparent -10distortion - 2colors in objects - 7Be creative - 10', '2002-07-02 00:11:00.000000', NULL, 1),
(79763, 2870, 1037, '<td valign="top">I really like this photo... something about it reminds me of "2001: A Space Odyssey". The only thing I don''t like is the harshness of the light, which makes the skin look a bit oily or something. I guess you had to do that to show the lens of the eye so clearly, but it''s not very aesthetically pleasing.</td>', 'I really like this photo... something about it reminds me of "2001: A Space Odyssey". The only thing I don''t like is the harshness of the light, which makes the skin look a bit oily or something. I guess you had to do that to show the lens of the eye so clearly, but it''s not very aesthetically pleasing.', '2002-07-02 02:44:00.000000', NULL, 1),
(79764, 2870, 1330, '<td valign="top">Had thought of doing this one also but still lack the expertise. Keep up the good work.</td>', 'Had thought of doing this one also but still lack the expertise. Keep up the good work.', '2002-07-02 09:42:00.000000', NULL, 1),
(79765, 2870, 2195, '<td valign="top">superb macro shot</td>', 'superb macro shot', '2002-07-02 10:20:00.000000', NULL, 1),
(79766, 2870, 2302, '<td valign="top">too bad for the big glare on the front of the eye. I like this one otherwise = 7</td>', 'too bad for the big glare on the front of the eye. I like this one otherwise = 7', '2002-07-02 16:42:00.000000', NULL, 1),
(79767, 2870, 1748, '<td valign="top">super shot really stands out,rest not a patch on it, sorry  ! bad joke</td>', 'super shot really stands out,rest not a patch on it, sorry  ! bad joke', '2002-07-02 17:00:00.000000', NULL, 1),
(79768, 2870, 1005, '<td valign="top">Wow, great macro.  Only complaint is the heavy glare below the eye and the lesser one above it.  I do like the shine ON the eye, so I guess it couldn''t be avoided.  Photo 9 Transparency 8 total 9 swash</td>', 'Wow, great macro.  Only complaint is the heavy glare below the eye and the lesser one above it.  I do like the shine ON the eye, so I guess it couldn''t be avoided.  Photo 9 Transparency 8 total 9 swash', '2002-07-02 20:09:00.000000', NULL, 1),
(79769, 2870, 1759, '<td valign="top">Cool shot, good job! I had to focus on this one a bit to grab hold of it, but when it hit it was with a lot of impact. My only suggestion would be to saturate the colors a bit more to bring out the iris.</td>', 'Cool shot, good job! I had to focus on this one a bit to grab hold of it, but when it hit it was with a lot of impact. My only suggestion would be to saturate the colors a bit more to bring out the iris.', '2002-07-02 22:13:00.000000', NULL, 1),
(79770, 2870, 1882, '<td valign="top">Incredible.  I may never look at an eye the same way again.  Fantastic macro with awesome detail and it fits the "transparent" category perfectly.</td>', 'Incredible.  I may never look at an eye the same way again.  Fantastic macro with awesome detail and it fits the "transparent" category perfectly.', '2002-07-03 11:33:00.000000', NULL, 1),
(79771, 2870, 2466, '<td valign="top">different background would be better</td>', 'different background would be better', '2002-07-03 13:11:00.000000', NULL, 1),
(79772, 2870, 1944, '<td valign="top">Good interpertation  of the challange. I know it''d be difficult, but it would have been better if you had more DOF, especially along the near eye lashes. The white balance seems to be a little off also. It might be interesting to see how the colors would look if you took a little blue out. The blue overpowers what should be more tan or yellowish in the skin tones. Also, if it were possible you might have reduced the contrast by reflecting some light into the shadow areas. That would have allowed you to have a little more DOF, and also would have kept the front of the eyelids from burning out. Paul.</td>', 'Good interpertation  of the challange. I know it''d be difficult, but it would have been better if you had more DOF, especially along the near eye lashes. The white balance seems to be a little off also. It might be interesting to see how the colors would look if you took a little blue out. The blue overpowers what should be more tan or yellowish in the skin tones. Also, if it were possible you might have reduced the contrast by reflecting some light into the shadow areas. That would have allowed you to have a little more DOF, and also would have kept the front of the eyelids from burning out. Paul.', '2002-07-03 14:16:00.000000', NULL, 1),
(79773, 2870, 714, '<td valign="top">creative 9 interesting 9 focus 9 framing 8 = 9</td>', 'creative 9 interesting 9 focus 9 framing 8 = 9', '2002-07-03 14:17:00.000000', NULL, 1),
(79774, 2870, 554, '<td valign="top">This is soooo nice!   Should be In the top 10   ----------10</td>', 'This is soooo nice!   Should be In the top 10   ----------10', '2002-07-03 23:39:00.000000', NULL, 1),
(79775, 2870, 2478, '<td valign="top">judging by the size of that iris, that flashburst in a dark room must''ve hurt! hope this didn''t require too many shots. you''ve a very longsuffering model (or is this a self-portrait?)</td>', 'judging by the size of that iris, that flashburst in a dark room must''ve hurt! hope this didn''t require too many shots. you''ve a very longsuffering model (or is this a self-portrait?)', '2002-07-04 01:14:00.000000', NULL, 1),
