(79904, 2879, 2199, '<td valign="top">Beautiful! Texture of the surface is great, and the weird pattern on the bottle in the upper left -- very cool!</td>', 'Beautiful! Texture of the surface is great, and the weird pattern on the bottle in the upper left -- very cool!', '2002-07-02 14:10:00.000000', NULL, 1),
