(79909, 2879, 1944, '<td valign="top">I like your slightly mysterious still life very much. Good graphic design and use of color. Very good technically. Paul.</td>', 'I like your slightly mysterious still life very much. Good graphic design and use of color. Very good technically. Paul.', '2002-07-04 00:27:00.000000', NULL, 1),
(79910, 2879, 2559, '<td valign="top">Wonderful colors and great light....I love it !</td>', 'Wonderful colors and great light....I love it !', '2002-07-05 20:05:00.000000', NULL, 1),
(79911, 2879, 772, '<td valign="top">excellent composition and lighting on this photo.  I really love the textures in the bottle.  The only minor complaint I have is that the surface is slightly busy with light and texture.  good shot! = 9 - jmsetzler</td>', 'excellent composition and lighting on this photo.  I really love the textures in the bottle.  The only minor complaint I have is that the surface is slightly busy with light and texture.  good shot! = 9 - jmsetzler', '2002-07-06 01:49:00.000000', NULL, 1),
(79912, 2879, 1054, '<td valign="top">Excellent shot.  I love the surreal effect of the lighting here.  Well-composed and well executed.</td>', 'Excellent shot.  I love the surreal effect of the lighting here.  Well-composed and well executed.', '2002-07-07 10:12:00.000000', NULL, 1),
(79913, 2879, 2221, '<td valign="top">very nice! quite abstract but i like it. good colors. what is that in the background? interesting texture.</td>', 'very nice! quite abstract but i like it. good colors. what is that in the background? interesting texture.', '2002-07-07 23:06:00.000000', NULL, 1),
(79914, 2880, 714, '<td valign="top">creative 4 interesting 4 focus 3 framing 3 = 3</td>', 'creative 4 interesting 4 focus 3 framing 3 = 3', '2002-07-01 01:55:00.000000', NULL, 1),
(79915, 2880, 1877, '<td valign="top">its too bad the suction cup is there.. and the dealie on the left is kind of distracting.. 5</td>', 'its too bad the suction cup is there.. and the dealie on the left is kind of distracting.. 5', '2002-07-01 02:43:00.000000', NULL, 1),
(79916, 2880, 1569, '<td valign="top">The suction cup kills this one--use real light test monofilament fishing linenext time,and punch up the colors.</td>', 'The suction cup kills this one--use real light test monofilament fishing linenext time,and punch up the colors.', '2002-07-01 14:18:00.000000', NULL, 1),
(79917, 2880, 1005, '<td valign="top">The window got you, just a bit with an extra reflection, otherwise, this is really nice.  Is it me, or is the butterfly slightly out of focus?  Photo 7 Transparency 7 total 7 swash</td>', 'The window got you, just a bit with an extra reflection, otherwise, this is really nice.  Is it me, or is the butterfly slightly out of focus?  Photo 7 Transparency 7 total 7 swash', '2002-07-01 16:56:00.000000', NULL, 1),
(79918, 2880, 327, '<td valign="top">Very nice shot, pretty. The background is distracting, but this is well done. Kee</td>', 'Very nice shot, pretty. The background is distracting, but this is well done. Kee', '2002-07-01 17:39:00.000000', NULL, 1),
(79919, 2880, 133, '<td valign="top">the background really adds to this shot.</td>', 'the background really adds to this shot.', '2002-07-01 19:24:00.000000', NULL, 1),
(79920, 2880, 2199, '<td valign="top">Nice colors...I like the green and blue in this photo. I wish the wings were tighter focus....</td>', 'Nice colors...I like the green and blue in this photo. I wish the wings were tighter focus....', '2002-07-01 23:19:00.000000', NULL, 1),
(79921, 2880, 2000, '<td valign="top">Good use of DOF - it makes the dragonfly suncatcher stand out nicely.</td>', 'Good use of DOF - it makes the dragonfly suncatcher stand out nicely.', '2002-07-02 11:57:00.000000', NULL, 1),
(79922, 2880, 772, '<td valign="top">I like the colors on this shot... I think the focus is just a tad soft, but other than that, nice image :) = 7 - jmsetzler</td>', 'I like the colors on this shot... I think the focus is just a tad soft, but other than that, nice image :) = 7 - jmsetzler', '2002-07-02 18:23:00.000000', NULL, 1),
(79923, 2880, 2146, '<td valign="top">ok</td>', 'ok', '2002-07-02 23:49:00.000000', NULL, 1),
(79924, 2880, 1041, '<td valign="top">cool idea, but the dragonfly doesn''t seem to be quite sharp.  did you slightly sharpen your shot after you resized it?  i think that would help here.  i like that you have distortion both in the dragon fly wings and the suction cup. -- gr8photos (5)</td>', 'cool idea, but the dragonfly doesn''t seem to be quite sharp.  did you slightly sharpen your shot after you resized it?  i think that would help here.  i like that you have distortion both in the dragon fly wings and the suction cup. -- gr8photos (5)', '2002-07-03 15:44:00.000000', NULL, 1),
(79925, 2880, 509, '<td valign="top">Nice idea, but the background is distracting... I think this would have looked better on a window with a sky or something a little bit simpler in the background, maybe to play on the nature theme (it is modelled after a dragonfly afterall = )</td>', 'Nice idea, but the background is distracting... I think this would have looked better on a window with a sky or something a little bit simpler in the background, maybe to play on the nature theme (it is modelled after a dragonfly afterall = )', '2002-07-05 16:24:00.000000', NULL, 1),
(79926, 2880, 1054, '<td valign="top">Nice execution of this shot.</td>', 'Nice execution of this shot.', '2002-07-07 13:24:00.000000', NULL, 1),
(79927, 2882, 1779, '<td valign="top">nice... : )</td>', 'nice... : )', '2002-07-01 12:56:00.000000', NULL, 1),
(79928, 2882, 2146, '<td valign="top">good</td>', 'good', '2002-07-01 14:40:00.000000', NULL, 1),
(79929, 2882, 714, '<td valign="top">creative 3 interesting 3 focus 6 framing 5 = 4</td>', 'creative 3 interesting 3 focus 6 framing 5 = 4', '2002-07-01 14:56:00.000000', NULL, 1),
(79930, 2882, 327, '<td valign="top">Nice work, good idea. Kee</td>', 'Nice work, good idea. Kee', '2002-07-01 15:53:00.000000', NULL, 1),
(79931, 2882, 1005, '<td valign="top">Nice, simple, well executed.  If anything, a bit plain.  The rattan is interesting, but busy and the rest of the background is plain.  I like the rainbow in the water.  Photo 8 Transparency 8 total 8 swash</td>', 'Nice, simple, well executed.  If anything, a bit plain.  The rattan is interesting, but busy and the rest of the background is plain.  I like the rainbow in the water.  Photo 8 Transparency 8 total 8 swash', '2002-07-01 17:01:00.000000', NULL, 1),
(79932, 2882, 772, '<td valign="top">This is an interesting photo... I think the lighting is a little strong and the tilt on the glass seems a little odd... = 6 - jmsetzler</td>', 'This is an interesting photo... I think the lighting is a little strong and the tilt on the glass seems a little odd... = 6 - jmsetzler', '2002-07-02 00:12:00.000000', NULL, 1),
(79933, 2882, 741, '<td valign="top">Very, very clever.  I''ve been dying to do a shot that''s all B&amp;W with one colour element but you beat me too it!<br/>Would have preferred the glass to be completely vertical.</td>', 'Very, very clever.  I''ve been dying to do a shot that''s all B&W with one colour element but you beat me too it!Would have preferred the glass to be completely vertical.', '2002-07-02 15:15:00.000000', NULL, 1),
(79934, 2882, 2478, '<td valign="top">very interesting shadow. don''t see that much, that effect of a hard, high light. cool.<br/>don''t care much for the wickerwork, though. a plainer, more solid base, to match the backdrop? or would that be too commercial?</td>', 'very interesting shadow. don''t see that much, that effect of a hard, high light. cool.don''t care much for the wickerwork, though. a plainer, more solid base, to match the backdrop? or would that be too commercial?', '2002-07-04 01:27:00.000000', NULL, 1),
(79935, 2882, 917, '<td valign="top">Its not vertical and you''ve cropped the botton off the glass. Also, rotating the table to get the wicker running horizontal would help the ''formality'' of the picture. Using fizzy water (or lemonade) could have helped the dead area in the bowl of the glass.</td>', 'Its not vertical and you''ve cropped the botton off the glass. Also, rotating the table to get the wicker running horizontal would help the ''formality'' of the picture. Using fizzy water (or lemonade) could have helped the dead area in the bowl of the glass.', '2002-07-05 11:47:00.000000', NULL, 1),
(79936, 2882, 2188, '<td valign="top">Odd angles? I like it though.</td>', 'Odd angles? I like it though.', '2002-07-06 23:14:00.000000', NULL, 1),
(79937, 2882, 1054, '<td valign="top">Excellent shot of the water glass.  I like the sharpness of the shadow and the play of light in the water.</td>', 'Excellent shot of the water glass.  I like the sharpness of the shadow and the play of light in the water.', '2002-07-07 15:35:00.000000', NULL, 1),
(79938, 2883, 1, '<td valign="top">Nice centering of the flame wher we can see it.  I wish it could be more clear, but that might be a limitation of the glass.</td>', 'Nice centering of the flame wher we can see it.  I wish it could be more clear, but that might be a limitation of the glass.', '2002-07-01 09:57:00.000000', NULL, 1),
(79939, 2883, 1175, '<td valign="top">This is a great photo.  I love all the abstract symettry.  If you could have shot this a little more even (seems to be more on the left then on the right) it would be better.</td>', 'This is a great photo.  I love all the abstract symettry.  If you could have shot this a little more even (seems to be more on the left then on the right) it would be better.', '2002-07-01 10:55:00.000000', NULL, 1),
(79940, 2883, 2000, '<td valign="top">Very nice use of light and distortion.</td>', 'Very nice use of light and distortion.', '2002-07-01 15:32:00.000000', NULL, 1),
(79941, 2883, 327, '<td valign="top">Nice work, good idea. Kee</td>', 'Nice work, good idea. Kee', '2002-07-01 15:56:00.000000', NULL, 1),
(79942, 2883, 641, '<td valign="top">I like the colors in this. I''d crop a little off the bottom if it were mine.</td>', 'I like the colors in this. I''d crop a little off the bottom if it were mine.', '2002-07-01 16:26:00.000000', NULL, 1),
(79943, 2883, 133, '<td valign="top">I always like shots like this.</td>', 'I always like shots like this.', '2002-07-01 19:15:00.000000', NULL, 1),
(79944, 2883, 2140, '<td valign="top">good idea using flame. really brings out the shape of the glass. good work!</td>', 'good idea using flame. really brings out the shape of the glass. good work!', '2002-07-01 20:59:00.000000', NULL, 1),
(79945, 2883, 1005, '<td valign="top">Nice warm feeling.  I don''t see anything all that wrong, so GREAT SHOT!  Photo 9 Transparency 9 total 9</td>', 'Nice warm feeling.  I don''t see anything all that wrong, so GREAT SHOT!  Photo 9 Transparency 9 total 9', '2002-07-02 16:55:00.000000', NULL, 1),
(79946, 2883, 772, '<td valign="top">I really love the concept of this image.  It looks to me like the post processing on this shot was a little excessive maybe... I''m not sure if the levels were adjusted this way, but the image quality is down for some reason.  I will check this one after the challenge to see what has been done to it... = 7 - jmsetzler</td>', 'I really love the concept of this image.  It looks to me like the post processing on this shot was a little excessive maybe... I''m not sure if the levels were adjusted this way, but the image quality is down for some reason.  I will check this one after the challenge to see what has been done to it... = 7 - jmsetzler', '2002-07-02 17:17:00.000000', NULL, 1),
(79947, 2883, 2004, '<td valign="top">I like these kind of colors, they create an ambience. Too bad, the glass is out of focus...</td>', 'I like these kind of colors, they create an ambience. Too bad, the glass is out of focus...', '2002-07-03 08:53:00.000000', NULL, 1);
