(80072, 2892, 2146, '<td valign="top">Love this one.</td>', 'Love this one.', '2002-07-01 14:38:00.000000', NULL, 1),
(80073, 2892, 2172, '<td valign="top">Really great work.  I like all of it - dof, contrast, composition/layout.  Only one thing though, could the white have been better?  I''ve had this problem in the past - white coming out more grey.  If this was intentional, then my apologies - personally would''ve liked it just a little brighter.  I''m new at this, and don''t want to be out of line - I''ve found that the white balance changed my photos .  But I really like this, creative, artistic - just a really great picture.  <br/>Ruthann</td>', 'Really great work.  I like all of it - dof, contrast, composition/layout.  Only one thing though, could the white have been better?  I''ve had this problem in the past - white coming out more grey.  If this was intentional, then my apologies - personally would''ve liked it just a little brighter.  I''m new at this, and don''t want to be out of line - I''ve found that the white balance changed my photos .  But I really like this, creative, artistic - just a really great picture.  Ruthann', '2002-07-01 14:47:00.000000', NULL, 1),
(80074, 2892, 2152, '<td valign="top">On the thumbnail I like it this way, but on the big image I think I''d like the flag to be right side up in the drops.  Whatever, I''m nitpicking, it''s awesome!</td>', 'On the thumbnail I like it this way, but on the big image I think I''d like the flag to be right side up in the drops.  Whatever, I''m nitpicking, it''s awesome!', '2002-07-01 16:09:00.000000', NULL, 1),
