(80344, 2909, 2000, '<td valign="top">I view the challenge as the veil being the primary point of focus.  As it''s not really visible here, this looks like a grainy rose.  Nice background, though.</td>', 'I view the challenge as the veil being the primary point of focus.  As it''s not really visible here, this looks like a grainy rose.  Nice background, though.', '2002-07-01 10:30:00.000000', NULL, 1),
(80345, 2909, 318, '<td valign="top">Almost like a canvas, that background is a bit distracting, though</td>', 'Almost like a canvas, that background is a bit distracting, though', '2002-07-01 11:18:00.000000', NULL, 1),
(80346, 2909, 772, '<td valign="top">I''m not sure about this one... is this rose under water? = 5 - jmsetzler</td>', 'I''m not sure about this one... is this rose under water? = 5 - jmsetzler', '2002-07-01 13:53:00.000000', NULL, 1),
