(80362, 2912, 133, '<td valign="top">Nice title.</td>', 'Nice title.', '2002-07-01 19:23:00.000000', NULL, 1),
(80363, 2912, 327, '<td valign="top">Very nice shot, well done. Kee</td>', 'Very nice shot, well done. Kee', '2002-07-01 19:55:00.000000', NULL, 1),
