(80532, 2922, 1037, '<td valign="top">I think this would be a lot cooler without that title. It encourages the viewer not to take it seriously, when it actually has a lot of artistic merit (at least to me). I love the way the eyes are stretched out like that :). Very weird and surreal.</td>', 'I think this would be a lot cooler without that title. It encourages the viewer not to take it seriously, when it actually has a lot of artistic merit (at least to me). I love the way the eyes are stretched out like that :). Very weird and surreal.', '2002-07-01 15:22:00.000000', NULL, 1),
(80533, 2922, 327, '<td valign="top">Clever work</td>', 'Clever work', '2002-07-01 19:27:00.000000', NULL, 1),
