(80535, 2922, 1880, '<td valign="top">Nice ...</td>', 'Nice ...', '2002-07-01 20:58:00.000000', NULL, 1),
(80536, 2922, 2154, '<td valign="top">interesting camera work, but title doesn''t fit.l</td>', 'interesting camera work, but title doesn''t fit.l', '2002-07-01 21:52:00.000000', NULL, 1),
(80537, 2922, 2186, '<td valign="top">Whoah! What a cool photo! This would make for an interesting "Photographers Self Portrait"! Really like the quality. lighting and effect. Good job!  Done in photoshop or with mirrors??</td>', 'Whoah! What a cool photo! This would make for an interesting "Photographers Self Portrait"! Really like the quality. lighting and effect. Good job!  Done in photoshop or with mirrors??', '2002-07-02 10:54:00.000000', NULL, 1),
(80538, 2922, 1005, '<td valign="top">Great effect, but seems more like a mirror.  Others in this challenge have found good glass that distorts somewhat like this, so I will give you the benefit of the doubt.  (if mirror, please deduct 5 points)  Photo 8 transparency 7 total 7 swash</td>', 'Great effect, but seems more like a mirror.  Others in this challenge have found good glass that distorts somewhat like this, so I will give you the benefit of the doubt.  (if mirror, please deduct 5 points)  Photo 8 transparency 7 total 7 swash', '2002-07-02 16:52:00.000000', NULL, 1),
