(80724, 2944, 2158, '<td valign="top">Lacks focus.</td>', 'Lacks focus.', '2002-07-01 20:47:00.000000', NULL, 1),
(80725, 2944, 2172, '<td valign="top">Good photography.  I like the shapes and colors-could''ve been a touch brighter for me, but still really good pic.  Good work.<br/>Ruthann</td>', 'Good photography.  I like the shapes and colors-could''ve been a touch brighter for me, but still really good pic.  Good work.Ruthann', '2002-07-01 22:28:00.000000', NULL, 1),
(80726, 2944, 772, '<td valign="top">Nice shot!  I think the foreground focus could be a little sharper thought... = 6 - jmsetzler</td>', 'Nice shot!  I think the foreground focus could be a little sharper thought... = 6 - jmsetzler', '2002-07-02 16:30:00.000000', NULL, 1),
(80727, 2944, 1005, '<td valign="top">Fun jumble of glass pieces.  Great focus and color.  Photo 8 Transparency 7 total 8 swash</td>', 'Fun jumble of glass pieces.  Great focus and color.  Photo 8 Transparency 7 total 8 swash', '2002-07-02 19:16:00.000000', NULL, 1),
(80728, 2944, 878, '<td valign="top">Simple but an effective shot for me.</td>', 'Simple but an effective shot for me.', '2002-07-03 13:50:00.000000', NULL, 1),
(80729, 2944, 1024, '<td valign="top">The colors in this photograph are lovely.  Unfortunately, I feel my eyes all over the place, there does not seem to be a subject that draws my attention.</td>', 'The colors in this photograph are lovely.  Unfortunately, I feel my eyes all over the place, there does not seem to be a subject that draws my attention.', '2002-07-03 14:03:00.000000', NULL, 1),
(80730, 2944, 1944, '<td valign="top">Watch your light sources and your focus. The stones would be a lot more effective with ultra sharp focus and DOF, and you would have had better lighting if you had used a softer source. Maybe bouncing the flash off the ceiling, or shielding the stones with a thin layer of white cloth or translucent plastic. It would have eliminated the hot spots that are a bit distracting, and if the light wern''t too soft you still would have had the definition. I like the design very much, and there is a lot that is interesting in your photo. Paul.</td>', 'Watch your light sources and your focus. The stones would be a lot more effective with ultra sharp focus and DOF, and you would have had better lighting if you had used a softer source. Maybe bouncing the flash off the ceiling, or shielding the stones with a thin layer of white cloth or translucent plastic. It would have eliminated the hot spots that are a bit distracting, and if the light wern''t too soft you still would have had the definition. I like the design very much, and there is a lot that is interesting in your photo. Paul.', '2002-07-04 00:16:00.000000', NULL, 1),
(80731, 2944, 1128, '<td valign="top">Wish the colors were a little more vivid, and that there was a different background other than the wood, but I like the idea and the lighting.</td>', 'Wish the colors were a little more vivid, and that there was a different background other than the wood, but I like the idea and the lighting.', '2002-07-07 10:06:00.000000', NULL, 1),
(80732, 2944, 1054, '<td valign="top">Excellent choice of subject!  Well-executed, too.</td>', 'Excellent choice of subject!  Well-executed, too.', '2002-07-07 11:06:00.000000', NULL, 1),
(80733, 2945, 641, '<td valign="top">Crop a little off the bottom and a little off the top. Other than that I really like this shot.</td>', 'Crop a little off the bottom and a little off the top. Other than that I really like this shot.', '2002-07-01 11:21:00.000000', NULL, 1),
