(80737, 2945, 133, '<td valign="top">This photo makes me want to know the story behind it. Great shot.</td>', 'This photo makes me want to know the story behind it. Great shot.', '2002-07-01 19:19:00.000000', NULL, 1),
(80738, 2945, 327, '<td valign="top">Very nice shot, well done. Kee</td>', 'Very nice shot, well done. Kee', '2002-07-01 19:39:00.000000', NULL, 1),
(80739, 2945, 1005, '<td valign="top">Good shot, I like most everything, but the glare to John''s right, the washed out sky and the dirty windows (add the reflected glare in front of John, too.)  Straight glass isn''t exactly a stellar effort for transparency, either.  Besides those, this is a great shot.  Photo 7 Transparency 3 total 5 swash</td>', 'Good shot, I like most everything, but the glare to John''s right, the washed out sky and the dirty windows (add the reflected glare in front of John, too.)  Straight glass isn''t exactly a stellar effort for transparency, either.  Besides those, this is a great shot.  Photo 7 Transparency 3 total 5 swash', '2002-07-02 20:00:00.000000', NULL, 1),
(80740, 2945, 1379, '<td valign="top">Hey!  John is really cute!  Let him in!</td>', 'Hey!  John is really cute!  Let him in!', '2002-07-02 23:21:00.000000', NULL, 1),
(80741, 2945, 1313, '<td valign="top">stay outside John</td>', 'stay outside John', '2002-07-03 22:15:00.000000', NULL, 1),
(80742, 2945, 772, '<td valign="top">Poor John :(  He does look like he wants to com inside... :)  This is a neat photo.  I love the simplicity and the statement :) good shot! = 8 - jmsetzler</td>', 'Poor John :(  He does look like he wants to com inside... :)  This is a neat photo.  I love the simplicity and the statement :) good shot! = 8 - jmsetzler', '2002-07-05 07:44:00.000000', NULL, 1),
(80743, 2945, 2558, '<td valign="top">although it would be too small for the challenge - crop out the trashcan, it doesn''t fit.</td>', 'although it would be too small for the challenge - crop out the trashcan, it doesn''t fit.', '2002-07-05 19:59:00.000000', NULL, 1),
(80744, 2945, 1054, '<td valign="top">Nice composition and framing, and I think I know who took this.  Remind me after the challenge to tell you if I was right, I''ll be honest.</td>', 'Nice composition and framing, and I think I know who took this.  Remind me after the challenge to tell you if I was right, I''ll be honest.', '2002-07-07 16:01:00.000000', NULL, 1),
(80745, 2946, 2363, '<td valign="top">Rather out-of-focus</td>', 'Rather out-of-focus', '2002-07-01 13:52:00.000000', NULL, 1),
(80746, 2946, 509, '<td valign="top">The sky seems overblown while the subject is dark.  I would suggest using a fill flash, but then you''d get reflections on the glass.  Also, the size of this is way below 150 kb, and the compression artifacts get in the way.  This may have looked better with a slow shutter (if your camera permits this control) at night to eliminate the overexposure.</td>', 'The sky seems overblown while the subject is dark.  I would suggest using a fill flash, but then you''d get reflections on the glass.  Also, the size of this is way below 150 kb, and the compression artifacts get in the way.  This may have looked better with a slow shutter (if your camera permits this control) at night to eliminate the overexposure.', '2002-07-01 14:46:00.000000', NULL, 1),
(80747, 2946, 1041, '<td valign="top">your photo is very pixelated.  i''m not sure whether that was an intent and you saved your file that small for that purpose, or not.  if not, there are some tutorials on this site that help you save the files so that your photos aren''t so pixelated.  you''ve met the challenge for sure (color and distortion), but the photo unfortunately doesn''t hold my interest for very long.  i''m also not quite sure what you should''ve done about it.  was there maybe a way of placing the oil in the kitchen (while still having light falling through it, could be artificial light) to tie it in with the background a little more?  i guess oil and garden don''t connect for me. -- gr8photos (3)</td>', 'your photo is very pixelated.  i''m not sure whether that was an intent and you saved your file that small for that purpose, or not.  if not, there are some tutorials on this site that help you save the files so that your photos aren''t so pixelated.  you''ve met the challenge for sure (color and distortion), but the photo unfortunately doesn''t hold my interest for very long.  i''m also not quite sure what you should''ve done about it.  was there maybe a way of placing the oil in the kitchen (while still having light falling through it, could be artificial light) to tie it in with the background a little more?  i guess oil and garden don''t connect for me. -- gr8photos (3)', '2002-07-01 17:05:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(80748, 2946, 741, '<td valign="top">Needs more light in the bottle - looks like it needs about 1.5 stops more (but then the background would burn out).  Maybe a closer crop and more exposure.</td>', 'Needs more light in the bottle - looks like it needs about 1.5 stops more (but then the background would burn out).  Maybe a closer crop and more exposure.', '2002-07-01 18:22:00.000000', NULL, 1),
(80749, 2946, 2343, '<td valign="top">Background is too complex, seek to make it simple.  Focus needs to be increased.  Try creating a stage with lights illuminating from behind to give the same effect yet more simple.</td>', 'Background is too complex, seek to make it simple.  Focus needs to be increased.  Try creating a stage with lights illuminating from behind to give the same effect yet more simple.', '2002-07-01 18:23:00.000000', NULL, 1),
(80750, 2946, 772, '<td valign="top">Ths composition on this shot is very nice... I like the position of the oil bottle :)  The focus on the bottle seems a little soft and this shot would be nicer, IMO, with less depth of field to blur out the background some more... = 6 - jmsetzler</td>', 'Ths composition on this shot is very nice... I like the position of the oil bottle :)  The focus on the bottle seems a little soft and this shot would be nicer, IMO, with less depth of field to blur out the background some more... = 6 - jmsetzler', '2002-07-02 00:14:00.000000', NULL, 1),
(80751, 2946, 2146, '<td valign="top">nice bottle</td>', 'nice bottle', '2002-07-02 02:51:00.000000', NULL, 1),
(80752, 2946, 436, '<td valign="top">I wish you could''ve captured the oil with stronger lighting to make it glow.  Good idea, though and nicely composed.</td>', 'I wish you could''ve captured the oil with stronger lighting to make it glow.  Good idea, though and nicely composed.', '2002-07-02 11:55:00.000000', NULL, 1),
(80753, 2946, 2000, '<td valign="top">Too much garden, not enough oil, IMO.</td>', 'Too much garden, not enough oil, IMO.', '2002-07-02 11:57:00.000000', NULL, 1),
(80754, 2946, 2302, '<td valign="top">I wish the camera angle was lower so you could see more through the bottle. Also a little dark in the lower half = 6</td>', 'I wish the camera angle was lower so you could see more through the bottle. Also a little dark in the lower half = 6', '2002-07-02 16:43:00.000000', NULL, 1),
(80755, 2946, 1005, '<td valign="top">Wayyyy to dark, more than hard to see.  You might want to try a different background, lighting, staging for this shot.  It has potential, but this view is toooo hard to see.  (I think you were going for the flower in the garden, but it barely shows up.)  Photo 6 Transparency 6 total 6</td>', 'Wayyyy to dark, more than hard to see.  You might want to try a different background, lighting, staging for this shot.  It has potential, but this view is toooo hard to see.  (I think you were going for the flower in the garden, but it barely shows up.)  Photo 6 Transparency 6 total 6', '2002-07-02 20:55:00.000000', NULL, 1),
(80756, 2946, 1054, '<td valign="top">Excellent composition and a great idea.</td>', 'Excellent composition and a great idea.', '2002-07-03 13:11:00.000000', NULL, 1),
(80757, 2946, 2337, '<td valign="top">Certainly ''met'' the challenge, but I think it would have been better with more Oil and less windowsill... The black stripe at the bottom below the sill killed this for me.</td>', 'Certainly ''met'' the challenge, but I think it would have been better with more Oil and less windowsill... The black stripe at the bottom below the sill killed this for me.', '2002-07-03 18:42:00.000000', NULL, 1),
(80758, 2946, 1031, '<td valign="top">I think I''d crop it narrower from the left, and maybe a little off the top, to focus on the subject more. I think there would still be plenty of background left.</td>', 'I think I''d crop it narrower from the left, and maybe a little off the top, to focus on the subject more. I think there would still be plenty of background left.', '2002-07-06 02:48:00.000000', NULL, 1),
(80759, 2947, 1779, '<td valign="top">¿?</td>', '¿?', '2002-07-01 13:34:00.000000', NULL, 1),
(80760, 2947, 1569, '<td valign="top">Tapping on the side of the glass would release the small bubbles.</td>', 'Tapping on the side of the glass would release the small bubbles.', '2002-07-01 16:14:00.000000', NULL, 1),
(80761, 2947, 705, '<td valign="top">great choice of subject-the words and the font are nice.  something''s unappealing about the lighting, not sure what, it just looks unnatural.  the bubbles are unfortunate.</td>', 'great choice of subject-the words and the font are nice.  something''s unappealing about the lighting, not sure what, it just looks unnatural.  the bubbles are unfortunate.', '2002-07-01 16:51:00.000000', NULL, 1),
(80762, 2947, 1005, '<td valign="top">very nice use of water, decent magnification.  Well taken shot.   Photo 8 Transparency 8 total 8 swash</td>', 'very nice use of water, decent magnification.  Well taken shot.   Photo 8 Transparency 8 total 8 swash', '2002-07-02 16:20:00.000000', NULL, 1),
(80763, 2947, 772, '<td valign="top">Interesting :)  = 6 - jmsetzler</td>', 'Interesting :)  = 6 - jmsetzler', '2002-07-02 16:31:00.000000', NULL, 1),
(80764, 2947, 2079, '<td valign="top">I like this - It looks slightly over exposed - Definitely meets the challenge</td>', 'I like this - It looks slightly over exposed - Definitely meets the challenge', '2002-07-03 20:43:00.000000', NULL, 1),
(80765, 2947, 2221, '<td valign="top">nice idea. good DOF. only some minor things, like why the glass is not centered? symmetry would be nice here. the thing on the right side is distracting but i guess it''s the handle, so it couldn''t be easily removed ;-) i would have tried to either zoom out to show the whole glass with the complete handle or zoom in so that the glass fills the whole photo and the handle is not visible.<br/>i don''t know if the text in the background has some meaning but i think another background with more colors would be more interesting.</td>', 'nice idea. good DOF. only some minor things, like why the glass is not centered? symmetry would be nice here. the thing on the right side is distracting but i guess it''s the handle, so it couldn''t be easily removed ;-) i would have tried to either zoom out to show the whole glass with the complete handle or zoom in so that the glass fills the whole photo and the handle is not visible.i don''t know if the text in the background has some meaning but i think another background with more colors would be more interesting.', '2002-07-06 22:05:00.000000', NULL, 1),
(80766, 2947, 1054, '<td valign="top">Nicely done.  I also like how you picked up the reflection at the top.</td>', 'Nicely done.  I also like how you picked up the reflection at the top.', '2002-07-07 16:37:00.000000', NULL, 1),
(80767, 2948, 789, '<td valign="top">creepy</td>', 'creepy', '2002-07-01 08:07:00.000000', NULL, 1),
(80768, 2948, 436, '<td valign="top">delightful!  and a most cooperative subject!   The dark background really sets it off</td>', 'delightful!  and a most cooperative subject!   The dark background really sets it off', '2002-07-01 10:14:00.000000', NULL, 1),
(80769, 2948, 1175, '<td valign="top">FREAKY!</td>', 'FREAKY!', '2002-07-01 12:36:00.000000', NULL, 1),
(80770, 2948, 1779, '<td valign="top">nice... : )</td>', 'nice... : )', '2002-07-01 13:05:00.000000', NULL, 1),
(80771, 2948, 772, '<td valign="top">cute kid :) = 5 - jmsetzler<br/><br/>Qualification:<br/><br/>I apologize for the blount comment with the score... i rate photos at a 5 that are ''average'' in my mind... now.. what would make this portrait better than average?<br/><br/>1. The pink linen doesn''t appear natural to me and it gives me the slight impression that she is being choked by it.  <br/>2. i think you are a little close to the subject.  I would like to either see a little more breathing room or a little less pink linen.  <br/>3. I believe that some vertical wrinkles in the linen would create some nice shadows on her face and would allow some more interesting dispersion of the light in this shot. <br/>4. I personally prefer lighting from a side angle for portrait shots.. about 45 degrees off center.<br/><br/>You did a great job with the catch lighting in her eyes... this is a very important element of a nice portrait shot :)<br/><br/>Please don''t take these critiques personally.  I was sincere with the ''cute kid'' remark.  Ms Susan is a cutie for sure :)  She''s lucky to have a dad that enjoys taking pictures... she will appreciate all of these one day for sure :)</td>', 'cute kid :) = 5 - jmsetzlerQualification:I apologize for the blount comment with the score... i rate photos at a 5 that are ''average'' in my mind... now.. what would make this portrait better than average?1. The pink linen doesn''t appear natural to me and it gives me the slight impression that she is being choked by it.  2. i think you are a little close to the subject.  I would like to either see a little more breathing room or a little less pink linen.  3. I believe that some vertical wrinkles in the linen would create some nice shadows on her face and would allow some more interesting dispersion of the light in this shot. 4. I personally prefer lighting from a side angle for portrait shots.. about 45 degrees off center.You did a great job with the catch lighting in her eyes... this is a very important element of a nice portrait shot :)Please don''t take these critiques personally.  I was sincere with the ''cute kid'' remark.  Ms Susan is a cutie for sure :)  She''s lucky to have a dad that enjoys taking pictures... she will appreciate all of these one day for sure :)', '2002-07-01 13:54:00.000000', NULL, 1),
(80772, 2948, 1877, '<td valign="top">Your child looks scared ;) but cute photo, 6</td>', 'Your child looks scared ;) but cute photo, 6', '2002-07-01 14:34:00.000000', NULL, 1),
(80773, 2948, 1759, '<td valign="top">Cute! Good exposure and composition.</td>', 'Cute! Good exposure and composition.', '2002-07-01 14:41:00.000000', NULL, 1),
(80774, 2948, 714, '<td valign="top">creative 3 interesting 2 focus 9 framing 6 = 5   This photo is really freaky for some reason.  I know it is probably your kid and all, but there is something about it that really bothers me.  I don''t know.  Please don''t take it to personal.</td>', 'creative 3 interesting 2 focus 9 framing 6 = 5   This photo is really freaky for some reason.  I know it is probably your kid and all, but there is something about it that really bothers me.  I don''t know.  Please don''t take it to personal.', '2002-07-01 15:06:00.000000', NULL, 1),
(80775, 2948, 1005, '<td valign="top">Cute and to this week''s theme.  Well done.  Maybe a little overly posed.  Photo 9 Transparency 7 total 8 swash</td>', 'Cute and to this week''s theme.  Well done.  Maybe a little overly posed.  Photo 9 Transparency 7 total 8 swash', '2002-07-01 15:10:00.000000', NULL, 1),
(80776, 2948, 2494, '<td valign="top">cool but that stare is a little creepy.</td>', 'cool but that stare is a little creepy.', '2002-07-01 16:12:00.000000', NULL, 1),
(80777, 2948, 705, '<td valign="top">I''m starting to agree with Iban about babies and kids.  Still...they''re cute.  Anyways-my eye goes straight to the exposed hair, and I don''t like that; completely covering the face would''ve been better, or cropping more severly to the left.  the way the face ends up floating is nice.</td>', 'I''m starting to agree with Iban about babies and kids.  Still...they''re cute.  Anyways-my eye goes straight to the exposed hair, and I don''t like that; completely covering the face would''ve been better, or cropping more severly to the left.  the way the face ends up floating is nice.', '2002-07-01 16:13:00.000000', NULL, 1),
(80778, 2948, 1856, '<td valign="top">What an adorable child.  For some reason this makes me think...why would you do that?  Great colors and image quality...but that question keeps bugging me. 7</td>', 'What an adorable child.  For some reason this makes me think...why would you do that?  Great colors and image quality...but that question keeps bugging me. 7', '2002-07-01 17:35:00.000000', NULL, 1),
