(80881, 2959, 1054, '<td valign="top">I wish you''d had at least a little more depth of field to add some interest to the background.</td>', 'I wish you''d had at least a little more depth of field to add some interest to the background.', '2002-07-07 15:34:00.000000', NULL, 1),
(80882, 2961, 1143, '<td valign="top">Bothersome background. Could have moved it to a better location or even put a piece of paper behind it. I like the close-up though and the reflecting light.</td>', 'Bothersome background. Could have moved it to a better location or even put a piece of paper behind it. I like the close-up though and the reflecting light.', '2002-07-01 02:46:00.000000', NULL, 1),
