INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(81148, 2980, 2154, '<td valign="top">very interesting interpretation of the challenge</td>', 'very interesting interpretation of the challenge', '2002-07-06 15:52:00.000000', NULL, 1),
(81149, 2980, 1128, '<td valign="top">cool effect!  You did this well, and I like the b&amp;W</td>', 'cool effect!  You did this well, and I like the b&W', '2002-07-07 09:56:00.000000', NULL, 1),
(81150, 2980, 1054, '<td valign="top">Nice effect, I''d love to know how you did this.  Please do share after the competition is over.</td>', 'Nice effect, I''d love to know how you did this.  Please do share after the competition is over.', '2002-07-07 10:04:00.000000', NULL, 1),
(81151, 2980, 2312, '<td valign="top">Okay, here are the details: First, I put the camera on a tripod to support it during a extremely long duration shot. Unfortunately, I didn''t have anyone who could assist me so I had to do this completely on my own, which didn''t prove to be easy. I illuminated myself using a flash, as many speculated. I set the flash (Nikon SB-28) on manual at 1/32 power, set the self timer, and walked into the shot. As soon as the flash fired, I quickly left the frame and allowed the ambient light to form the rest of the exposure. The disappointing thing, at least to me, is that this shot was actually one of a series of many shots to simply test this concept. Once I proved that I could successfully pull it off in-camera, I had a much more elaborate shot planned. Unfortunately, I became sick with a cold and was not able to do it. So as a last ditch effort, I submitted this picture to gauge what the response would be. But you can be certain that I will incorporate my original idea in some future submission.</td>', 'Okay, here are the details: First, I put the camera on a tripod to support it during a extremely long duration shot. Unfortunately, I didn''t have anyone who could assist me so I had to do this completely on my own, which didn''t prove to be easy. I illuminated myself using a flash, as many speculated. I set the flash (Nikon SB-28) on manual at 1/32 power, set the self timer, and walked into the shot. As soon as the flash fired, I quickly left the frame and allowed the ambient light to form the rest of the exposure. The disappointing thing, at least to me, is that this shot was actually one of a series of many shots to simply test this concept. Once I proved that I could successfully pull it off in-camera, I had a much more elaborate shot planned. Unfortunately, I became sick with a cold and was not able to do it. So as a last ditch effort, I submitted this picture to gauge what the response would be. But you can be certain that I will incorporate my original idea in some future submission.', '2002-07-08 01:39:00.000000', NULL, 0),
(81152, 2980, 2278, '<td valign="top">Sorry, but I had to stick this worthless comment on your entry cause I want to enter next week.</td>', 'Sorry, but I had to stick this worthless comment on your entry cause I want to enter next week.', '2002-07-11 19:18:00.000000', NULL, 0),
(81153, 2981, 705, '<td valign="top">I think everything''s out of focus in this shot, isn''t it?  Yes, it''s a contact lens, in contact with a finger.  Hm, it doesn''t convey anything, no story.  The background, even totally out of focus, as it should be, is still distracting.  Nice capture of the blues in the rim.</td>', 'I think everything''s out of focus in this shot, isn''t it?  Yes, it''s a contact lens, in contact with a finger.  Hm, it doesn''t convey anything, no story.  The background, even totally out of focus, as it should be, is still distracting.  Nice capture of the blues in the rim.', '2002-07-01 03:09:00.000000', NULL, 1),
(81154, 2981, 142, '<td valign="top">Good idea.  This is well executed and original.</td>', 'Good idea.  This is well executed and original.', '2002-07-01 09:37:00.000000', NULL, 1),
(81155, 2981, 1, '<td valign="top">Very nicely shot though I think your focal point may be off a bit.</td>', 'Very nicely shot though I think your focal point may be off a bit.', '2002-07-01 10:00:00.000000', NULL, 1),
(81156, 2981, 1853, '<td valign="top">good idea, but needs sharper focus</td>', 'good idea, but needs sharper focus', '2002-07-01 11:02:00.000000', NULL, 1),
(81157, 2981, 1569, '<td valign="top">Needs more attention to focus.</td>', 'Needs more attention to focus.', '2002-07-01 14:05:00.000000', NULL, 1),
(81158, 2981, 1877, '<td valign="top">hmm, maybe if you had put the contact on something more interesting than a finger? something to show through the contact.. colors.. words..etc 4</td>', 'hmm, maybe if you had put the contact on something more interesting than a finger? something to show through the contact.. colors.. words..etc 4', '2002-07-01 14:32:00.000000', NULL, 1),
