(81160, 2981, 327, '<td valign="top">Nice work, very-very good idea. l  would of liked a bit more focus on the lens but this is well done. Kee</td>', 'Nice work, very-very good idea. l  would of liked a bit more focus on the lens but this is well done. Kee', '2002-07-01 15:52:00.000000', NULL, 1),
(81161, 2981, 1204, '<td valign="top">Although I think I get the point - and the out-of-focus is intentional - I really don''t it adds to the picture.</td>', 'Although I think I get the point - and the out-of-focus is intentional - I really don''t it adds to the picture.', '2002-07-01 19:53:00.000000', NULL, 1),
